window.generateRandomMixedExam = function() {
  var t1 = window.EXAM_DATA_LIST["1"];
  var t2 = window.EXAM_DATA_LIST["2"];
  if (!t1 || !t2) return window.EXAM_DATA_LIST["3"];

  function sample(arr, n) {
    var sh = arr.slice();
    for (var i = sh.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = sh[i]; sh[i] = sh[j]; sh[j] = tmp;
    }
    return sh.slice(0, n);
  }
  function shuffle(arr) {
    for (var i = arr.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
    }
    return arr;
  }
  function clone(obj) {
    return JSON.parse(JSON.stringify(obj));
  }

  var p1 = shuffle(sample(t1.parts[0].groups, 3).concat(sample(t2.parts[0].groups, 3)));
  var n1 = Math.random() < 0.5 ? 13 : 12;
  var p2 = shuffle(sample(t1.parts[1].groups, n1).concat(sample(t2.parts[1].groups, 25 - n1)));
  var g1 = Math.random() < 0.5 ? 7 : 6;
  var p3 = shuffle(sample(t1.parts[2].groups, g1).concat(sample(t2.parts[2].groups, 13 - g1)));
  var p4 = shuffle(sample(t1.parts[3].groups, 5).concat(sample(t2.parts[3].groups, 5)));
  var p5 = shuffle(sample(t1.parts[4].groups, 15).concat(sample(t2.parts[4].groups, 15)));
  var p6 = shuffle(sample(t1.parts[5].groups, 2).concat(sample(t2.parts[5].groups, 2)));

  // Part 7: Single passages (summing to 30)
  var s1 = t1.parts[6].groups.slice(0, 10);
  var s2 = t2.parts[6].groups.slice(0, 10);
  var p7Single = [];
  for (var iter = 0; iter < 100; iter++) {
    var sub1 = sample(s1, 5);
    var sub2 = sample(s2, 5);
    var tot = sub1.concat(sub2).reduce(function(acc, g) { return acc + g.questions.length; }, 0);
    if (tot === 30) {
      p7Single = shuffle(sub1.concat(sub2));
      break;
    }
  }
  if (p7Single.length === 0) p7Single = s1;

  // Part 7: Multi passages (summing to 24)
  var m1 = t1.parts[6].groups.slice(10);
  var m2 = t2.parts[6].groups.slice(10);
  var p7Multi = [];
  for (var iter = 0; iter < 100; iter++) {
    var take1 = Math.random() < 0.5 ? 2 : 3;
    var sub1 = sample(m1, take1);
    var sub2 = sample(m2, 5 - take1);
    var tot = sub1.concat(sub2).reduce(function(acc, g) { return acc + g.questions.length; }, 0);
    if (tot === 24) {
      p7Multi = shuffle(sub1.concat(sub2));
      break;
    }
  }
  if (p7Multi.length === 0) p7Multi = m1;

  var p7 = p7Single.concat(p7Multi);
  var allGroups = [p1, p2, p3, p4, p5, p6, p7];
  var partNames = [
    "Photographs", "Question-Response", "Conversations", "Short Talks",
    "Incomplete Sentences", "Text Completion", "Reading Comprehension"
  ];

  var curQ = 1;
  var newParts = [];

  allGroups.forEach(function(groups, pIdx) {
    var clonedGroups = [];
    groups.forEach(function(g) {
      var gClone = clone(g);
      gClone.questions.forEach(function(q) {
        var oldText = q.text || '';
        var cleanBody = oldText.replace(/^(Question\s*)?\d+[\.:\s]*/i, '').trim();
        q.qNum = curQ;
        q.text = cleanBody ? curQ + '. ' + cleanBody : 'Question ' + curQ + ':';
        if (q.cleanTitle) {
          q.cleanTitle = cleanBody ? cleanBody : 'Question ' + curQ + ':';
        }
        curQ++;
      });
      clonedGroups.push(gClone);
    });

    newParts.push({
      partNumber: pIdx + 1,
      name: partNames[pIdx],
      totalQuestions: clonedGroups.reduce(function(acc, g) { return acc + g.questions.length; }, 0),
      groups: clonedGroups
    });
  });

  return {
    testId: 3,
    testCount: 3,
    insiderName: "ULSA - Đề Xáo Trộn Ngẫu Nhiên (Mix Đề 1 & Đề 2)",
    title: "ULSA - Luyện tập",
    titleEn: "ULSA Practice Test - Random Mixed",
    totalQuestions: curQ - 1,
    timeMinutes: 120,
    parts: newParts
  };
};

(function() {
  var selected = 1;
  try {
    var saved = localStorage.getItem('TOEIC_SELECTED_TEST_ID');
    if (saved && window.EXAM_DATA_LIST[saved]) {
      selected = parseInt(saved, 10);
    }
  } catch(e) {}
  window.CURRENT_TEST_ID = selected;
  if (selected === 3) {
    window.EXAM_DATA_LIST["3"] = window.generateRandomMixedExam();
  }
  window.EXAM_DATA = window.EXAM_DATA_LIST[selected] || window.EXAM_DATA_LIST[1];
})();
